
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_rlda_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_rlda", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.511131997236058e+00, -2.047122036340246e+00, -2.701577678532278e+00, -3.433838911731737e+00, -4.135559947567260e+00, -4.609643016924058e+00, -4.596493131368387e+00, -3.903896280584717e+00, -2.635927379241715e+00, -1.312056351918418e+00, -5.524363410897887e-01, -5.299444940832565e-01, -7.874812860067795e-01, -7.424705818340545e-01, -4.078624080304414e-01, -1.245620588837413e-01, -1.873262780642748e-02, -1.096501585424975e-03, -1.660572124377155e-05, -3.638780417886669e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


